<template>
  <section class="review">
    <header class="review-heading"><div><span>图像检测结果</span><h3>{{ areaLabel }}</h3></div><p>检测目标包含非人数检测框和红外异常热点</p></header>
    <div class="review-metrics"><div><span>当前区域照片</span><b>{{ photos.length }}<small>张</small></b></div><div><span>已返回检测结果</span><b>{{ returned }}<small>张</small></b></div><div><span>含检测目标</span><b>{{ detected }}<small>张</small></b></div><div><span>需关注执行状态</span><b class="amber">{{ attention }}<small>张</small></b></div></div>
    <div class="review-tools"><el-input v-model="search" clearable placeholder="搜索照片名称 / 航点" aria-label="搜索分析照片" /><el-select v-model="filter" aria-label="检测结果筛选"><el-option label="全部照片" value="all" /><el-option label="含检测目标（不含人数）" value="detected" /><el-option label="已返回结果" value="returned" /><el-option label="有标注图" value="annotated" /><el-option label="执行异常 / 不可判断" value="attention" /><el-option label="尚无结果" value="pending" /></el-select><span>{{ filtered.length }} 张匹配</span></div>
    <div v-if="filtered.length" class="review-layout">
      <aside class="review-list" aria-label="分析照片列表"><button v-for="(photo, index) in pagePhotos" :key="photo.file_id" :class="{ active: selected?.file_id === photo.file_id }" @click="selectedId = photo.file_id"><span class="photo-number">{{ String((page - 1) * 8 + index + 1).padStart(2, '0') }}</span><span class="list-copy"><b :title="photo.name">{{ photo.name }}</b><small>{{ typeText(photo.type) }} · 航点 {{ photo.waypoint_index ?? '未匹配' }}</small><span :class="['state', { amber: needsAttention(photo) }]">{{ photo.excluded ? '已排除' : photoStatus(photo.status) }}</span></span><span class="list-arrow">›</span></button><el-pagination v-model:current-page="page" :page-size="8" :total="filtered.length" small layout="prev, pager, next" :pager-count="5" hide-on-single-page /></aside>
      <article v-if="selected" class="review-detail">
        <header class="photo-heading"><div><h4>{{ selected.name }}</h4><p>{{ areaName(selected.area_id) }} · {{ typeText(selected.type) }} · 航点 {{ selected.waypoint_index ?? '未匹配' }}</p></div><el-button @click="emit('preview', selected)">放大对比</el-button></header>
        <div v-loading="imageBusy" class="evidence-pair"><section v-for="kind in imageKinds" :key="kind"><header>{{ kind === 'original' ? '原始采集照片' : (selected.infrared_temperature_enabled ? '本地测温热力图' : '算法标注图') }}<span>{{ kind === 'original' ? '原图' : '本批次' }}</span></header><button v-if="images[kind]" class="evidence-image" @click="emit('preview', selected)"><img :src="images[kind]" :alt="kind === 'original' ? '原始采集照片' : (selected.infrared_temperature_enabled ? '本地测温热力图' : '算法标注图')" @error="imageErrors[kind] = '图片无法显示'; images[kind] = ''" /></button><div v-else class="evidence-empty"><span>▧</span>{{ imageErrors[kind] || (imageBusy ? '正在读取图片…' : '尚无图像证据') }}</div></section></div>
        <div class="evidence-note"><span>标注图用于核对算法输出，缺图不代表无隐患。</span><el-button link @click="loadImages">重新加载图片</el-button></div>
        <p v-if="selected.message" class="result-notice">{{ selected.message }}</p>
        <div class="checks-heading"><h4>逐项检测</h4><span>{{ selected.result?.checks?.length || 0 }} 项已返回</span></div>
        <div v-if="selected.result?.checks?.length" class="check-grid"><section v-for="(item, i) in selected.result.checks" :key="item.code + i" :class="['check-card', { uncertain: item.status !== 'success' }]"><header><b>{{ checkText(item.code) }}</b><span class="state">{{ statusText(item.status) }}</span></header><strong v-if="item.code === 'person_count'">{{ countText({ status: item.status, count: item.count ?? null }) }}<small>人 · 单张照片</small></strong><strong v-else-if="item.status === 'success' && item.boxes">{{ item.boxes.length }}<small>个检测框</small></strong><p v-if="item.label">{{ item.label }}<span v-if="typeof item.score === 'number'"> · 置信度 {{ (item.score * 100).toFixed(1) }}%</span></p><p v-if="item.message">{{ item.message }}</p><p v-if="item.status === 'success' && !item.boxes && !item.label && item.code !== 'person_count'">检测已完成，服务未提供目标明细</p></section></div>
        <div v-else-if="!selected.infrared_temperature_enabled" class="result-notice">{{ selected.excluded ? '本照片已排除，不参与分析。' : '尚无逐项检测结果，不能据此判断无隐患。' }}</div>
        <section v-if="selected.infrared_temperature?.status === 'success'" class="thermal-summary">
          <h4>本地红外测温 · {{ selected.infrared_temperature.abnormal ? '发现温度异常' : '未发现符合阈值的热点' }}</h4>
          <div class="check-grid"><div class="check-card"><header>最高 / 最低 / 平均温度</header><strong>{{ temperature(selected.infrared_temperature.max_temperature_c) }}<small>℃ · 最高温</small></strong><p>最低 {{ temperature(selected.infrared_temperature.min_temperature_c) }}℃ · 平均 {{ temperature(selected.infrared_temperature.average_temperature_c) }}℃</p></div><div class="check-card"><header>热点判定</header><strong>{{ selected.infrared_temperature.hotspot_count }}<small>个连通热点区域</small></strong><p>温度 ≥ {{ temperature(selected.infrared_temperature.threshold_c) }}℃，区域 ≥ {{ selected.infrared_temperature.min_hotspot_pixels }} 像素</p></div></div>
          <p class="result-notice">热力图由SDK温度矩阵生成，白框为符合条件的热点区域。温度异常不直接等同失火；单独高温像素可能未达到最小区域要求。</p>
          <details class="review-details"><summary>热点坐标与峰值温度</summary><p v-for="(hotspot, i) in selected.infrared_temperature.hotspots || []" :key="i">区域 {{ i + 1 }}：{{ hotspot.rect.join(', ') }}（x、y、宽、高） · {{ hotspot.pixels }} 像素 · {{ temperature(hotspot.max_temperature_c) }}℃</p></details>
        </section>
        <p v-if="selected.infrared_temperature" class="result-notice">红外测温：{{ statusText(selected.infrared_temperature.status) }} {{ selected.infrared_temperature.message }}</p>
        <details class="review-details"><summary>查看本照片冻结检测配置</summary><p>配置来源：{{ sourceLabel(selected.policy_source) }}</p><p>{{ selected.metadataSource || '执行时冻结快照' }}</p><div class="check-tags"><span v-for="code in selected.checks || []" :key="code">{{ checkText(code) }}</span><span v-if="!selected.checks?.length">未勾选可见光检测项</span></div><p v-if="selected.infrared_temperature_enabled">本照片请求红外测温，实际执行状态以服务返回为准。</p></details>
        <details v-if="selected.result" class="review-details"><summary>原始检测结果 / 坐标与置信度</summary><pre>{{ JSON.stringify(selected.result, null, 2) }}</pre></details>
      </article>
    </div>
    <el-empty v-else :description="photos.length ? '没有符合筛选条件的照片' : '当前区域暂无逐图结果'" :image-size="75"><el-button v-if="photos.length" @click="search = ''; filter = 'all'">清除筛选</el-button></el-empty>
  </section>
</template>

<script setup lang="ts">
import { computed, defineProps, defineEmits, onBeforeUnmount, ref, watch } from 'vue'
import type { ConstructionAnalysisPhoto } from '/@/api/construction'
import { getConstructionPhoto, getConstructionResultPhoto } from '/@/api/construction'
import { checkText, countText, statusText, typeText } from '../constructionAnalysis/model'
const props = defineProps<{ photos: ConstructionAnalysisPhoto[]; jobId: string; batchId: string; areaLabel: string; areaName:(id?: string) => string }>()
const emit = defineEmits<{(event: 'preview', photo: ConstructionAnalysisPhoto): void }>()
const search = ref(''); const filter = ref('all'); const page = ref(1); const selectedId = ref('')
function temperature (value?: number) { return typeof value === 'number' && Number.isFinite(value) ? value.toFixed(1) : '—' }
function needsAttention (p: ConstructionAnalysisPhoto) { return !p.excluded && (['FAILED', 'PARTIAL', 'failed', 'unavailable', 'unassessable'].includes(p.status || '') || !!p.result?.image_error || !!p.result?.checks?.some(c => ['failed', 'unavailable', 'unassessable'].includes(c.status))) }
const returned = computed(() => props.photos.filter(p => p.result).length)
function hasTargets (p: ConstructionAnalysisPhoto) { return !p.excluded && (p.infrared_temperature?.abnormal === true || !!p.result?.checks?.some(c => c.code !== 'person_count' && c.status === 'success' && (c.boxes?.length || 0) > 0)) }
function photoStatus (status?: string) { return status === 'SUCCEEDED' ? '检测完成' : status === 'FAILED' ? '检测失败' : statusText(status || '') }
const detected = computed(() => props.photos.filter(hasTargets).length)
const attention = computed(() => props.photos.filter(needsAttention).length)
const filtered = computed(() => props.photos.filter(p => (!search.value.trim() || `${p.name} 航点 ${p.waypoint_index ?? ''}`.toLowerCase().includes(search.value.trim().toLowerCase())) && (filter.value === 'all' || (filter.value === 'detected' && hasTargets(p)) || (filter.value === 'returned' && !!p.result) || (filter.value === 'annotated' && !!p.image_url) || (filter.value === 'attention' && needsAttention(p)) || (filter.value === 'pending' && !p.result && !p.excluded))))
const pagePhotos = computed(() => filtered.value.slice((page.value - 1) * 8, page.value * 8))
const selected = computed(() => pagePhotos.value.find(p => p.file_id === selectedId.value) || pagePhotos.value[0])
watch([search, filter, () => props.areaLabel, () => props.batchId, () => props.jobId], () => { page.value = 1; selectedId.value = '' })
watch(filtered, list => { page.value = Math.min(page.value, Math.max(1, Math.ceil(list.length / 8))) })
function sourceLabel (source?: string) { return ({ default: '平台默认', area: '工作面配置', point: '航点配置', waypoint: '航点配置' } as Record<string, string>)[source || ''] || source || '历史记录未提供' }
const imageKinds = ['original', 'result'] as const
const images = ref({ original: '', result: '' }); const imageErrors = ref({ original: '', result: '' }); const imageBusy = ref(false)
let generation = 0
function release () { generation++; Object.values(images.value).forEach(url => { if (url) URL.revokeObjectURL(url) }); images.value = { original: '', result: '' } }
async function loadImages () {
  release(); const token = generation; const photo = selected.value; const job = props.jobId; const batch = props.batchId
  imageErrors.value = { original: '', result: photo?.result?.image_error || '' }; imageBusy.value = false
  if (!photo) return
  imageBusy.value = true
  await Promise.all(imageKinds.map(async kind => {
    if (kind === 'result' && (!batch || !photo.image_url)) { imageErrors.value.result ||= '本照片尚无标注图'; return }
    try { const blob = kind === 'original' ? await getConstructionPhoto(job, photo.file_id) : await getConstructionResultPhoto(job, batch, photo.file_id); if (token === generation) images.value[kind] = URL.createObjectURL(blob) } catch { if (token === generation) imageErrors.value[kind] = kind === 'original' ? '原图读取失败，请确认原图已归档' : '标注图暂不可用，可重新加载' }
  }))
  if (token === generation) imageBusy.value = false
}
watch([() => selected.value?.file_id, () => selected.value?.image_url, () => props.batchId, () => props.jobId], loadImages, { immediate: true })
onBeforeUnmount(release)
</script>

