.review h3,.review h4{color:#dceafa}.review-list{align-self:start;max-height:740px;overflow-y:auto}.review{margin-top:20px;color:#dceafa;min-width:0}.review-heading,.review-tools,.photo-heading,.checks-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.review-heading>div>span{font-size:11px;letter-spacing:2px;color:#6bbfef}.review-heading h3{margin:6px 0 14px;font-size:18px}.review-heading p,.review-tools>span{color:#8da8c3;font-size:12px}.review-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:18px}.review-metrics>div{border:1px solid #294a69;background:linear-gradient(125deg,#163d5b,#102940);border-radius:8px;padding:15px}.review-metrics span{color:#98b4ce;font-size:12px}.review-metrics b{display:block;font-size:27px;margin-top:7px;font-weight:500}.review-metrics small{font-size:11px;color:#8ba5be;margin-left:8px}.amber{color:#f1bd76!important}.review-tools{justify-content:flex-start;margin-bottom:16px;flex-wrap:wrap}.review-tools :deep(.el-input){width:240px}.review-tools :deep(.el-select){width:205px}.review-layout{display:grid;grid-template-columns:260px minmax(0,1fr);border:1px solid #2b4a68;border-radius:8px;overflow:hidden}.review-list{background:#0b223b;padding:10px;border-right:1px solid #2b4a68;min-width:0}.review-list>button{width:100%;display:flex;text-align:left;align-items:center;gap:10px;padding:15px 10px;background:transparent;border:1px solid transparent;border-bottom-color:#213c57;color:#bfd1e3;cursor:pointer;border-radius:5px}.review-list>button:hover{background:#143451}.review-list>button.active{background:#194667;border-color:#3f88b6}.photo-number{font-size:12px;color:#73bcea}.list-copy{min-width:0;flex:1}.list-copy b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:500}.list-copy small{display:block;color:#92afc9;font-size:11px;margin:7px 0}.state{font-size:11px;color:#83c8e9}.list-arrow{font-size:24px;color:#73bcea}.review-list :deep(.el-pagination){margin-top:14px;justify-content:center;flex-wrap:wrap}.review-detail{padding:20px;background:#102c46;min-width:0}.photo-heading{align-items:flex-start;margin-bottom:18px}.photo-heading>div{min-width:0}.photo-heading h4{font-size:14px;overflow-wrap:anywhere;margin:0 0 8px;color:#e1efff}.photo-heading p{font-size:12px;color:#8eacc8;margin:0}.evidence-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.evidence-pair>section{min-width:0;border:1px solid #34516b;border-radius:6px;overflow:hidden;background:#071a2c}.evidence-pair header{display:flex;justify-content:space-between;padding:10px 12px;font-size:12px;background:#193750;color:#c4dbed}.evidence-pair header span{font-size:10px;color:#79badd}.evidence-image{width:100%;height:240px;display:block;padding:0;border:0;background:#071a2c;cursor:zoom-in}.evidence-image img{width:100%;height:100%;object-fit:contain}.evidence-empty{height:240px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:#87a2bb;font-size:12px;text-align:center;padding:20px}.evidence-empty>span{font-size:32px;color:#446783}.evidence-note{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;color:#89a6bf;font-size:11px;margin:8px 0 18px}.checks-heading h4{font-size:14px;margin:0 0 14px}.checks-heading>span{font-size:11px;color:#91acc4}.check-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.check-card{border:1px solid #31536d;border-left:3px solid #4ca8c1;background:#13334d;border-radius:5px;padding:13px;min-width:0}.check-card.uncertain{border-left-color:#d5a35f;background:#303b45}.check-card header{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}.check-card header b{font-size:12px;font-weight:500}.check-card strong{font-size:24px;font-weight:500;display:block;margin-top:12px}.check-card strong small{font-size:11px;margin-left:8px;color:#9eb6cc}.check-card p{font-size:12px;line-height:1.7;color:#adc4d8;margin:10px 0 0;overflow-wrap:anywhere}.result-notice{padding:12px;background:#243c4e;border-left:2px solid #c59d67;color:#d5c5a7;font-size:12px;line-height:1.7}.review-details{margin-top:14px;border-top:1px solid #2b4b66;padding-top:14px;color:#93afc8;font-size:12px}.review-details summary{cursor:pointer;color:#abc7de}.review-details pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;padding:12px;background:#0b2137}.check-tags{display:flex;flex-wrap:wrap;gap:7px}.check-tags span{padding:4px 8px;border:1px solid #3a5872;border-radius:4px}
@media(max-width:1200px){.review-layout{grid-template-columns:210px minmax(0,1fr)}.evidence-image,.evidence-empty{height:185px}.review-detail{padding:14px}}
@media(max-width:950px){.review-layout{grid-template-columns:1fr}.review-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-right:0;border-bottom:1px solid #2b4a68}.review-list :deep(.el-pagination){grid-column:1/-1}.review-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.review-heading{flex-wrap:wrap;gap:0}}
@media(max-width:520px){.evidence-pair,.check-grid,.review-list{grid-template-columns:1fr}.review-tools :deep(.el-input),.review-tools :deep(.el-select){width:100%}.photo-heading{flex-wrap:wrap}}
@media(min-width:1100px) and (max-height:850px){.review .evidence-image,.review .evidence-empty{height:160px}.review{margin-top:10px}}
</style>
